	int numberOfRows = grid.length;
	int numberOfCols = grid[0].length;

	for (int row = 0; row < numberOfRows; row++) {
		for (int col = 0; col < numberOfCols; col++) {
			if (grid[row][col] == '@') {
				DFS(grid, row, col);
				count++;
			}
		}
	}

	return count;
