    if (curr[0] == end[0] && curr[1] == end[1]) {
        return true;
    }
    for (int i = 0; i < paths.length; i++) {
        int[] adj = paths[i];
        if (visited[adj[0]][adj[1]] == false) {
            visited[adj[0]][adj[1]] = true;
            if (traverse(n, curr, end, Paths, visited)) {
                return true;
            }
            visited[adj[0]][adj[1]] = false;
        }
    }
    return false;
}
