public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize variables
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    boolean[] visited = new boolean[n];
    visited[0] = true;

    // BFS to find the minimum distance from node 0 to all other nodes
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < edges.length; j++) {
            int src = edges[j][0], dest = edges[j][1];
            if (!visited[src] || !visited[dest]) {
                continue;
            }
            int weight = dist[src] + 1;
            if (dist[dest] > weight) {
                dist[dest] = weight;
            }
        }
    }

    // Find the minimum distance from node 0 to a node that has an apple
    int minDist = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        if (hasApple[i] && dist[i] < minDist) {
            minDist = dist[i];
        }
    }

    // Return the minimum time required to collect all the apples and return to node 0
    return minDist * 2;
}
