public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize an array to store the minimum time required to collect each apple
    int[] minTimeArr = new int[n];

    // Initialize a queue to store the nodes to be processed
    Queue<Integer> queue = new LinkedList<>();

    // Enqueue node 0
    queue.add(0);

    // Loop through the queue and process each node
    while (!queue.isEmpty()) {
        int node = queue.remove();
        minTimeArr[node] = hasApple[node] ? 0 : Integer.MAX_VALUE;

        // Loop through the edges of the current node
        for (int[] edge : edges) {
            int toNode = edge[0] == node ? edge[1] : edge[0];

            // If the to node is not already processed, enqueue it and update its minimum time
            if (minTimeArr[toNode] == Integer.MAX_VALUE) {
                queue.add(toNode);
                minTimeArr[toNode] = Math.min(minTimeArr[toNode], minTimeArr[node] + 1);
            }
        }
    }

    // Return the minimum time required to collect all the apples and return to node 0
    return minTimeArr[0];
}
