private int minCostClimbingStairsHelper(int[] cost, int index) {
    if (index == cost.length - 1) {
        return cost[index];
    } else if (index == cost.length - 2) {
        return Math.min(cost[index] + cost[index + 1], cost[index]);
    }

    if (memo[index] > 0) {
        return memo[index];
    }

    int minCost = Math.min(minCostClimbingStairsHelper(cost, index + 1), minCostClimbingStairsHelper(cost, index + 2));
    memo[index] = cost[index] + minCost;
    return memo[index];
}

