    if (cost.length == 1) return cost[0];
    if (cost.length == 2) return Math.min(cost[0], cost[1]);

    int minCost1 = cost[0] + minCostClimbingStairs(Arrays.copyOfRange(cost, 2, cost.length));
    int minCost2 = cost[1] + minCostClimbingStairs(Arrays.copyOfRange(cost, 3, cost.length));

