public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) {
        dp[i][i] = 1;
    }
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            int sum = A[i] + A[j];
            if (isPerfectSquare(sum)) {
                dp[i][j] = dp[i + 1][j - 1];
            }
        }
    }
    return dp[0][n - 1];
}

private static boolean isPerfectSquare(int n) {
    int i = 1;
    while (i * i <= n) {
