    String digits = String.valueOf(n);

    // Iterate over the digits of the input integer
    for (int i = 0; i < digits.length(); i++) {
        // Get the current digit
        char digit = digits.charAt(i);

        // Check if the current digit is not a 0
        if (digit != '0') {
            // Rearrange the digits to form a new integer
            String rearranged = digits.substring(i + 1) + digit;

            // Convert the rearranged string to an integer
            int newNumber = Integer.parseInt(rearranged);

            // Check if the new integer is greater than the input integer
            if (newNumber > n) {
                // Check if the new integer is smaller than the current smallest rearranged integer
                if (smallest == -1 || newNumber < smallest) {
                    // Update the smallest rearranged integer
                    smallest = newNumber;
                }
            }
        }
    }

    // Return the smallest rearranged integer or -1 if not possible
    return smallest;
